$fixtureRoot = (Resolve-Path -LiteralPath 'C:\taki-c1a-fixture-86700c396b3348a7addf83ffc8273674').Path
$probeRoot = Join-Path $fixtureRoot 'rename-probe'
if (Test-Path -LiteralPath $probeRoot) { throw 'probe must be new' }
if ([IO.File]::ReadAllText((Join-Path $fixtureRoot '.c1a-owned-fixture')) -ne 'C1A_FAKE_ONLY') { throw 'not owned' }
[IO.Directory]::CreateDirectory($probeRoot) | Out-Null
$resolvedProbe = (Resolve-Path -LiteralPath $probeRoot).Path
if ([IO.Directory]::GetParent($resolvedProbe).FullName -ne $fixtureRoot) { throw 'outside fixture' }
$leafPath = Join-Path $resolvedProbe 'catalog.bin'
$stagePath = Join-Path $resolvedProbe 'stage.bin'
[IO.File]::WriteAllText($leafPath, 'FAKE_A')
[IO.File]::WriteAllText($stagePath, 'FAKE_B')
$leafStream = [IO.File]::Open($leafPath, [IO.FileMode]::Open, [IO.FileAccess]::Read, [IO.FileShare]::ReadWrite -bor [IO.FileShare]::Delete)
$whileOpen = 'pass'
try { [IO.File]::Move($stagePath, $leafPath, $true) } catch { $whileOpen = $_.Exception.InnerException.HResult }
finally { $leafStream.Dispose() }
$afterClose = 'already moved while open'
if (Test-Path -LiteralPath $stagePath) { [IO.File]::Move($stagePath, $leafPath, $true); $afterClose = 'pass' }
@{ fixture = $resolvedProbe; readWriteDeleteSharing = $true; whileLeafOpen = $whileOpen; afterLeafClose = $afterClose } | ConvertTo-Json

$ErrorActionPreference = 'Stop'
$fixtureRoot = (Resolve-Path -LiteralPath 'C:\taki-c1a-fixture-86700c396b3348a7addf83ffc8273674').Path
if ([IO.File]::ReadAllText((Join-Path $fixtureRoot '.c1a-owned-fixture')) -ne 'C1A_FAKE_ONLY') { throw 'not owned' }
$probeRoot = Join-Path $fixtureRoot 'directory-share-probe'
if (Test-Path -LiteralPath $probeRoot) { throw 'probe must be new' }
[IO.Directory]::CreateDirectory($probeRoot) | Out-Null
Add-Type -TypeDefinition @'
using System;
using System.Runtime.InteropServices;
using Microsoft.Win32.SafeHandles;
public static class C1aDirectoryProbe {
    [DllImport("kernel32.dll", CharSet = CharSet.Unicode, SetLastError = true)]
    public static extern SafeFileHandle CreateFileW(string name, uint access, uint share, IntPtr security, uint creation, uint flags, IntPtr template);
}
'@
$results = foreach ($share in @(1, 3, 5, 7)) {
    $caseRoot = Join-Path $probeRoot ('share-' + $share)
    $guardedPath = [IO.Path]::GetFullPath((Join-Path $caseRoot 'guarded'))
    $renamedPath = [IO.Path]::GetFullPath((Join-Path $caseRoot 'renamed'))
    foreach ($candidate in @($guardedPath, $renamedPath)) { if (-not $candidate.StartsWith($fixtureRoot + '\', [StringComparison]::OrdinalIgnoreCase)) { throw 'outside fixture' } }
    [IO.Directory]::CreateDirectory($guardedPath) | Out-Null
    $leafPath = Join-Path $guardedPath 'secret-catalog.bin'
    $stagePath = Join-Path $guardedPath 'stage.bin'
    [IO.File]::WriteAllText($leafPath, 'FAKE_A')
    [IO.File]::WriteAllText($stagePath, 'FAKE_B')
    $handle = [C1aDirectoryProbe]::CreateFileW($guardedPath, 0x20081, $share, [IntPtr]::Zero, 3, 0x2200000, [IntPtr]::Zero)
    if ($handle.IsInvalid) { throw ('open failed ' + [Runtime.InteropServices.Marshal]::GetLastWin32Error()) }
    $leafResult = 'pass'
    $parentResult = 'pass'
    try {
        try { [IO.File]::Move($stagePath, $leafPath, $true) } catch { $leafResult = $_.Exception.GetBaseException().HResult -band 0xffff }
        try { [IO.Directory]::Move($guardedPath, $renamedPath) } catch { $parentResult = $_.Exception.GetBaseException().HResult -band 0xffff }
    } finally { $handle.Dispose() }
    [PSCustomObject]@{ share = $share; leafReplacement = $leafResult; parentRename = $parentResult }
}
$results | ConvertTo-Json
